head.script:
scwin.screenId = "uldmgt50316";

///////// 1. 변수 및 선언 영역 /////////

scwin.frame = undefined;


///////// 2. 초기화 영역 /////////

// [A] 초기 목록 미해결 — uldmgt50316: 진입 키 updateonlinedisclosurelawdetail 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50316.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_lawItems_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_lawItems_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_lawItems');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_lawItems'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.lawContentDetail === 'function') { await scwin.lawContentDetail(r["lawItmSeq"]); } else { console.error('[sdd] 행 동작 미정의: scwin.lawContentDetail (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.lawContentDetail'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_lawItems.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_DetailList_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_DetailList_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_DetailList_xhr", unresolved: "action:self_submit:tx_fn_DetailList_xhr" };
};

/**
 * @method
 * @name scwin.tx_fn_DelDetail_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_DelDetail_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_DelDetail_xhr", unresolved: "action:self_submit:tx_fn_DelDetail_xhr" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.addDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param lawItmSeq
 * @returns
 * @hidden N
*/
scwin.addDetail = async function (lawItmSeq) {
    /* sdd-asis-lifecycle:begin fn_AddDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/uldmgt50317/uldmgt50317.xml?method=prepareUpdateDisclosureLawByitemDetailedRule&mode=create" + "&lawNo=" + dma_disclosureLaw.get("lawNo") + "&dtruleLawNo=" + dma_disclosureLawDetail.get("lawNo") + "&lawItmSeq=" + lawItmSeq;
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "lawDetailPop", popupName: "lawDetailPop" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.detailList
 * @author Inswave
 * @date 2026. 09. 29
 * @param lawItmSeq
 * @returns
 * @hidden N
*/
scwin.detailList = async function (lawItmSeq) {
    /* sdd-asis-lifecycle:begin fn_DetailList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_DetailListXhrReq').set('lawItmSeq', lawItmSeq);
    scwin.form_listForm.action = "/filing/updateOnlineDisclosureLawDetail.do";
    $c.util.getComponent('dma_DetailListXhrReq').set('method', "findDisclosureLawByitemDetailedRules");
    ($c.util.getComponent("document.all.byitemDetailDiv" + lawItmSeq) && $c.util.getComponent("document.all.byitemDetailDiv" + lawItmSeq).setValue) ? $c.util.getComponent("document.all.byitemDetailDiv" + lawItmSeq).setValue(await scwin.tx_fn_DetailList_xhr()) : (($c.util.getComponent("document.all.byitemDetailDiv" + lawItmSeq) && $c.util.getComponent("document.all.byitemDetailDiv" + lawItmSeq).setText) ? $c.util.getComponent("document.all.byitemDetailDiv" + lawItmSeq).setText(await scwin.tx_fn_DetailList_xhr()) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "document.all.byitemDetailDiv" + lawItmSeq), void (await scwin.tx_fn_DetailList_xhr())));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.delDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param lawItmSeq dtruleLawItmSeq dtruleLawItmTitle
 * @returns
 * @hidden N
*/
scwin.delDetail = async function (lawItmSeq, dtruleLawItmSeq, dtruleLawItmTitle) {
    /* sdd-asis-lifecycle:begin fn_DelDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _confirm = await $c.win.confirm("세칙항목 '" + dtruleLawItmTitle + "'를\n삭제하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.util.getComponent('dma_DetailListXhrReq').set('lawItmSeq', lawItmSeq);
    $c.util.getComponent('dma_DetailListXhrReq').set('dtruleLawItmSeq', dtruleLawItmSeq);
    scwin.form_listForm.action = "/filing/updateOnlineDisclosureLawDetail.do";
    $c.util.getComponent('dma_DetailListXhrReq').set('method', "deleteDisclosureLawByitemDetailedRule");
    ($c.util.getComponent("document.all.byitemDetailDiv" + lawItmSeq) && $c.util.getComponent("document.all.byitemDetailDiv" + lawItmSeq).setValue) ? $c.util.getComponent("document.all.byitemDetailDiv" + lawItmSeq).setValue(await scwin.tx_fn_DelDetail_xhr()) : (($c.util.getComponent("document.all.byitemDetailDiv" + lawItmSeq) && $c.util.getComponent("document.all.byitemDetailDiv" + lawItmSeq).setText) ? $c.util.getComponent("document.all.byitemDetailDiv" + lawItmSeq).setText(await scwin.tx_fn_DelDetail_xhr()) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "document.all.byitemDetailDiv" + lawItmSeq), void (await scwin.tx_fn_DelDetail_xhr())));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.lawContentDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param lawItmSeq
 * @returns
 * @hidden N
*/
scwin.lawContentDetail = async function (lawItmSeq) {
    /* sdd-asis-lifecycle:begin fn_LawContentDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/onlineDisclosureLaw.do?method=findDisclosureLawItemContent" + "&lawNo=" + dma_disclosureLaw.get("lawNo") + "&lawItmSeq=" + lawItmSeq;
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "lawContentPop", popupName: "lawContentPop" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.lawContentOnlyDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param dtruleLawItmSeq
 * @returns
 * @hidden N
*/
scwin.lawContentOnlyDetail = async function (dtruleLawItmSeq) {
    /* sdd-asis-lifecycle:begin fn_LawContentOnlyDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/onlineDisclosureLaw.do?method=findDisclosureLawItemContent" + "&lawNo=" + dma_disclosureLawDetail.get("lawNo") + "&lawItmSeq=" + dtruleLawItmSeq;
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "lawContentPop", popupName: "lawContentPop" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.lawItemList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.lawItemList = function () {
    /* sdd-asis-lifecycle:begin fn_LawItemList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/onlineDisclosureLaw.do?method=findDisclosureLawItemDisplay&lawNo=" + dma_disclosureLaw.get("lawNo") + "";
    goURL(_url);
    /* sdd-asis-lifecycle:end */
};
